{
  "type": "object",
  "required": ["emails"],
  "properties": {
    "emails": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "from", "subject", "date", "body", "priority", "category", "subfolder", "needs_reply", "reason"],
        "properties": {
          "id": { "type": "string", "description": "Short unique id like email-1" },
          "from": { "type": "string", "description": "Sender name and address" },
          "subject": { "type": "string", "description": "Email subject line" },
          "date": { "type": "string", "description": "Date the email was sent" },
          "body": { "type": "string", "description": "Plain-text body of the email" },
          "priority": { "type": "string", "enum": ["high", "medium", "low"], "description": "Urgency level" },
          "category": { "type": "string", "description": "Short category label" },
          "subfolder": { "type": "string", "description": "Suggested subfolder path" },
          "needs_reply": { "type": "boolean", "description": "Whether the email calls for a response" },
          "reason": { "type": "string", "description": "One sentence explaining the sort decision" }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": ["subject", "body"],
  "properties": {
    "subject": { "type": "string", "description": "Reply subject line starting with Re: " },
    "body": { "type": "string", "description": "Full reply text in plain text" }
  },
  "additionalProperties": false
}
